import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-04 — Chi tiết dự án","description":"","frontmatter":{"title":"SC-04 — Chi tiết dự án"},"headers":[],"relativePath":"wireframes/public/sc-04-chi-tiet-du-an.md","filePath":"wireframes/public/sc-04-chi-tiet-du-an.md","lastUpdated":1791606799000}'),l={name:"wireframes/public/sc-04-chi-tiet-du-an.md"};function c(p,n,d,e,o,h){return a(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="sc-04-—-chi-tiet-du-an-noxh" tabindex="-1">SC-04 — Chi tiết dự án NOXH <a class="header-anchor" href="#sc-04-—-chi-tiet-du-an-noxh" aria-label="Permalink to &quot;SC-04 — Chi tiết dự án NOXH&quot;">​</a></h1><p><span class="wf-badge muted">ĐỘ PHỨC TẠP: THẤP</span> <span class="wf-badge info">Route: /du-an/[id]</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-04 · docs/06 §4.10 · docs/07 §2.4 · docs/08 BR-HS-06</span></p><p><strong>Ai xem màn này</strong>: Guest + Thành viên muốn hiểu bối cảnh dự án trước khi xem tin; chủ nhà tương lai muốn biết <strong>giá trần bán lại</strong> của dự án mình. <strong>Mục đích / cảm xúc thiết kế</strong>: trang hồ sơ dự án khách quan — số liệu hành chính (tổng căn, tầng, pháp lý, tiến độ) + <strong>giá trần/m² là nhân vật chính</strong> vì nó quyết định tin đăng không được vượt bao nhiêu. Không marketing chủ đầu tư. <strong>Ví dụ số dùng trong bản vẽ</strong>: dự án <code>NOXH Nhà ở xã hội HP-380</code> · 380 Võ Nguyên Giáp, Vĩnh Niệm, Lê Chân, Hải Phòng · giá dự kiến <code>22.000.000 ₫/m²</code> · <strong>trần bán lại <code>30.000.000 ₫/m²</code></strong> · 480 căn · 15 tầng · khởi công 2024 · bàn giao 2027 (dữ liệu mẫu docs/06 §4.10).</p><h2 id="_1-desktop-—-ho-so-du-an-gia-tran-noi-bat-tin-cung-du-an" tabindex="-1">1. Desktop — hồ sơ dự án + giá trần nổi bật + tin cùng dự án <a class="header-anchor" href="#_1-desktop-—-ho-so-du-an-gia-tran-noi-bat-tin-cung-du-an" aria-label="Permalink to &quot;1. Desktop — hồ sơ dự án + giá trần nổi bật + tin cùng dự án&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/du-an/prj_01JZK3M9W2Q8T1V5X7Y9ZBCDEF</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span class="active">Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng nhập</span><span class="wf-btn sm primary">Đăng bán</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Mua nhà › Dự án › <b>NOXH HP-380</b></div><div class="wf-row between middle"><div class="wf-col" style="gap:4px;"><span class="wf-title xl">NOXH Nhà ở xã hội HP-380 <span class="wf-callout">1</span></span><span class="wf-text">380 Võ Nguyên Giáp · Vĩnh Niệm · Lê Chân · Hải Phòng</span><div class="wf-row wrap" style="gap:6px;margin-top:4px;"><span class="wf-badge warn">Đang xây dựng</span><span class="wf-badge ok">Đủ điều kiện bán</span><span class="wf-badge muted">Chung cư</span></div></div><div class="wf-col" style="gap:4px;align-items:flex-end;"><span class="wf-small">Chủ đầu tư</span><span class="wf-strong">Công ty TNHH Nhà ở xã hội An Phúc</span></div></div><div class="wf-card" style="margin-top:16px;border:2px solid var(--wf-ink);background:var(--wf-accent-soft);"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-title lg">💰 Giá trần bán lại: <span class="wf-money lg">30.000.000 ₫/m²</span> <span class="wf-callout">2</span></span><span class="wf-text">Mọi tin đăng bán lại căn thuộc dự án này <b>không được vượt đơn giá trần trên</b> — sàn từ chối duyệt tin vượt trần theo quy định NOXH.</span></div><div class="wf-col" style="gap:2px;align-items:flex-end;"><span class="wf-small">Giá bán dự kiến (chủ đầu tư)</span><span class="wf-money">22.000.000 ₫/m²</span></div></div></div><div class="wf-grid" style="margin-top:16px;"><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Thông tin tổng quan <span class="wf-callout">3</span></span><table class="wf-table"><tbody><tr><td>Tổng số căn</td><td><b>480</b></td><td>Số tầng</td><td><b>15</b></td></tr><tr><td>Mật độ xây dựng</td><td><b>45%</b></td><td>Loại hình</td><td>Chung cư (APARTMENT)</td></tr><tr><td>Khởi công</td><td><b>2024</b></td><td>Bàn giao dự kiến</td><td><b>2027</b></td></tr><tr><td>Tiến độ</td><td colspan="3"><span class="wf-badge warn">CONSTRUCTING — đang xây dựng</span></td></tr><tr><td>Pháp lý dự án</td><td colspan="3"><span class="wf-badge ok">SALES_ELIGIBLE — đủ điều kiện bán</span></td></tr></tbody></table><span class="wf-small">Cập nhật lần cuối 10/10/2026 15:00 (GMT+7) — ADMIN cập nhật tiến độ thời gian thực <span class="wf-callout">4</span></span></div></div><div class="wf-col" style="gap:12px;"><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Loại căn hộ</span><table class="wf-table"><thead><tr><th>Loại căn</th><th>Diện tích</th><th>Số căn</th></tr></thead><tbody><tr><td>2 phòng ngủ</td><td>69,5 m²</td><td>120</td></tr><tr><td>2 phòng ngủ (góc)</td><td>72 m²</td><td>60</td></tr><tr><td>1 phòng ngủ</td><td>45 m²</td><td>300</td></tr></tbody></table></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">Tiện ích</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-badge muted">Công viên nội khu</span><span class="wf-badge muted">Trường mầm non</span></div></div></div></div></div><div class="wf-card flat" style="margin-top:12px;"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Mô tả dự án</span><div class="wf-lines"><span class="w-100"></span><span class="w-90"></span><span class="w-75"></span></div><span class="wf-small">&quot;Dự án NOXH 15 tầng, 2 hầm…&quot; — text ≤5.000 ký tự do ADMIN nhập.</span></div></div><div class="wf-row between middle" style="margin-top:20px;"><span class="wf-title lg">Tin đăng tại dự án này (8) <span class="wf-callout">5</span></span><span class="wf-small wf-accent">Lọc nâng cao → SC-02?projectId=…</span></div><div class="wf-col" style="gap:8px;margin-top:10px;"><div class="wf-card"><div class="pad wf-row middle"><div class="wf-img" style="width:110px;min-height:74px;flex:none;"><span>ẢNH</span></div><div class="wf-grow wf-col" style="gap:2px;"><span class="wf-row between middle"><span class="wf-title">Căn CT2-A18.05 <span class="wf-badge wf-vip">★ VIP</span></span><span class="wf-badge ok">Đang bán</span></span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng · 17.361.111 ₫/m² ✓ dưới trần</span></div><div class="wf-col" style="align-items:flex-end;gap:2px;"><span class="wf-money lg">1.250.000.000 ₫</span><span class="wf-small">Đăng 02/10/2026 08:00</span></div></div></div><div class="wf-card"><div class="pad wf-row middle"><div class="wf-img" style="width:110px;min-height:74px;flex:none;"><span>ẢNH</span></div><div class="wf-grow wf-col" style="gap:2px;"><span class="wf-row between middle"><span class="wf-title">Căn CT2-A11.02</span><span class="wf-badge muted">Sắp đấu giá</span></span><span class="wf-text">70 m² · 2 PN · 1 WC · tầng 11 · Sổ hồng · phiên mở 12/10/2026 14:00</span></div><div class="wf-col" style="align-items:flex-end;gap:2px;"><span class="wf-money lg">Khởi điểm 1.800.000.000 ₫</span><span class="wf-small">→ xem phiên SC-05/06</span></div></div></div><span class="wf-small">… 6 tin nữa — list dạng hàng (row), không grid, để quét nhanh đơn giá /m² so với trần</span></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">›</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-04 · docs/06 §4.10 · docs/08)</div><ol><li><span class="num">1</span><span>Dữ liệu từ `GET /projects/{id}` (🌐 public, endpoint 12). Payload <b>không chứa `createdBy`</b> — ai tạo/sửa chỉ tra qua audit; UI không có chỗ nào hiện &quot;người tạo&quot;. 404 → message chuẩn &quot;Không tìm thấy dự án&quot;. <span class="ref">docs/06 §4.10</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">2</span><span><b>Giá trần là khối nổi bật nhất trang</b> (viền đậm + nền accent): `resalePriceCapM2` = trần bán lại NOXH theo dự án (nguồn Sở Xây dựng, ADMIN nhập, pháp chế duyệt). Tin đăng có đơn giá = floor(giá/diện tích) vượt trần này → bị từ chối lúc submit với message &quot;Giá vượt trần {cap} ₫/m² của dự án theo quy định&quot;. <span class="ref">BR-HS-06</span> <span class="ref">docs/07 §2.4</span></span></li><li><span class="num">3</span><span>Badge trạng thái dự án map enum `ProjectStatus`: PLANNING/PREPARING/CONSTRUCTING = warn, FINISHING/HANDOVER/COMPLETED = ok, SUSPENDED = danger. `legalStatus` hiển thị nhãn tiếng Việt: SALES_ELIGIBLE = &quot;Đủ điều kiện bán&quot; (ok), DISPUTED = &quot;Đang tranh chấp&quot; (danger — thêm note cảnh báo). <span class="ref">docs/07 §2.4</span></span></li><li><span class="num">4</span><span>&quot;Cập nhật lần cuối&quot; = `updatedAt` — ADMIN PATCH tiến độ thời gian thực (endpoint 51). <b>Không vẽ</b> ảnh dự án, bản đồ GPS, thanh % milestone, lịch thanh toán — các trường này chưa có trong schema, cấm mock. <span class="ref">docs/06 §4.10</span> <span class="ref">docs/07 §2.4</span></span></li><li><span class="num">5</span><span>Tin cùng dự án = `GET /housing?projectId=…&amp;sort=newest` (chỉ LISTED/RESERVED/SOLD). Mỗi row hiện <b>đơn giá /m² + dấu ✓ dưới trần</b> để người xem tự kiểm chứng BR-HS-06. Click row → SC-03. &quot;Lọc nâng cao&quot; → SC-02 preselect projectId. <span class="ref">FR-HS-06</span></span></li><li><span class="num">6</span><span>Trạng thái nền: <b>Loading</b> = skeleton khối thông tin + 2 row tin; <b>Error</b> = hộp lỗi + traceId + &quot;Thử lại&quot; (pattern SC-02 §5); <b>404</b> = &quot;Không tìm thấy dự án&quot; + link về SC-02. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_2-mobile-360px-—-gia-tran-len-đau-table-xep-doc" tabindex="-1">2. Mobile 360px — giá trần lên đầu, table xếp dọc <a class="header-anchor" href="#_2-mobile-360px-—-gia-tran-len-đau-table-xep-doc" aria-label="Permalink to &quot;2. Mobile 360px — giá trần lên đầu, table xếp dọc&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm primary">Đăng bán</span></div><div class="wf-container" style="padding:12px;"><span class="wf-title lg">NOXH Nhà ở xã hội HP-380</span><span class="wf-text">380 Võ Nguyên Giáp · Vĩnh Niệm · Lê Chân · Hải Phòng</span><div class="wf-row wrap" style="gap:6px;margin-top:6px;"><span class="wf-badge warn">Đang xây dựng</span><span class="wf-badge ok">Đủ điều kiện bán</span></div><div class="wf-card" style="margin-top:12px;border:2px solid var(--wf-ink);background:var(--wf-accent-soft);"><div class="pad wf-col" style="gap:2px;"><span class="wf-small">GIÁ TRẦN BÁN LẠI</span><span class="wf-money lg">30.000.000 ₫/m²</span><span class="wf-small">Tin đăng dự án này không được vượt đơn giá trên</span><span class="wf-text" style="margin-top:4px;">Giá dự kiến CĐT: <b>22.000.000 ₫/m²</b></span></div></div><div class="wf-card flat" style="margin-top:12px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">Tổng quan</span><div class="wf-row between"><span class="wf-text">Tổng số căn · tầng</span><span class="wf-strong">480 · 15</span></div><div class="wf-row between"><span class="wf-text">Mật độ xây dựng</span><span class="wf-strong">45%</span></div><div class="wf-row between"><span class="wf-text">Khởi công · bàn giao</span><span class="wf-strong">2024 · 2027</span></div><div class="wf-row between"><span class="wf-text">Chủ đầu tư</span><span class="wf-strong">Cty TNHH NOXH An Phúc</span></div></div></div><div class="wf-row between middle" style="margin-top:14px;"><span class="wf-title">Tin tại dự án (8)</span><span class="wf-small wf-accent">Tất cả →</span></div><div class="wf-card" style="margin-top:8px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-title">Căn CT2-A18.05 ★</span><span class="wf-badge ok">Đang bán</span></span><span class="wf-text">72 m² · 2 PN · tầng 18 · 17,4 tr/m² ✓ dưới trần</span><span class="wf-money">1.250.000.000 ₫</span></div></div><div class="wf-card" style="margin-top:8px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-title">Căn CT2-A11.02</span><span class="wf-badge muted">Sắp đấu giá</span></span><span class="wf-text">70 m² · 2 PN · tầng 11 · mở 12/10/2026 14:00</span><span class="wf-money">Khởi điểm 1.800.000.000 ₫</span></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — vận hành bởi An Phuc</span><span>CSKH 1900-xxx</span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Khối <b>giá trần được đẩy lên ngay dưới tên dự án</b> (desktop đặt sau header) — mobile ưu tiên thông tin ra quyết định. Table tổng quan chuyển thành row &quot;nhãn — giá trị&quot; xếp dọc; row tin bỏ ảnh thumb (dành chiều rộng cho đơn giá ✓ trần).</span></li></ol></div><h2 id="_3-empty-—-du-an-chua-co-tin-đang" tabindex="-1">3. Empty — dự án chưa có tin đăng <a class="header-anchor" href="#_3-empty-—-du-an-chua-co-tin-đang" aria-label="Permalink to &quot;3. Empty — dự án chưa có tin đăng&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:560px;"><span class="wf-state-label">TRẠNG THÁI: EMPTY (GET /housing?projectId=… trả 0 tin)</span><div class="wf-empty"><span class="icon">🏗</span><span class="wf-title">Chưa có tin đăng tại dự án này</span><br><span class="wf-text">Dự án vẫn đang trong giai đoạn xây dựng (bàn giao dự kiến 2027). Tin bán lại sẽ xuất hiện khi có căn đủ điều kiện chuyển nhượng.</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Xem dự án NOXH khác → SC-02</span><span class="wf-btn ghost">Nhận thông báo khi có tin</span></div></div><div class="wf-note">Hồ sơ dự án (giá trần, loại căn, tiện ích) <b>vẫn hiển thị đầy đủ</b> khi empty — chỉ khối &quot;Tin đăng&quot; thay bằng empty state. Nút &quot;Nhận thông báo&quot; = opt-in notification (v1: ghi nhận qua bell/NTF system, không phải tính năng riêng).</div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">7</span><span>Empty của khối tin ≠ empty toàn trang: dữ liệu dự án đến từ endpoint khác (`GET /projects/{id}`) nên 2 khối load/empty/error độc lập. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_4-checklist-designer-khi-dung-figma-cho-sc-04" tabindex="-1">4. Checklist designer khi dựng Figma cho SC-04 <a class="header-anchor" href="#_4-checklist-designer-khi-dung-figma-cho-sc-04" aria-label="Permalink to &quot;4. Checklist designer khi dựng Figma cho SC-04&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop 1024/1440 (2 cột thông tin + list tin full-width) / tablet 768 / mobile 360 (giá trần lên đầu trang)</li><li>[ ] Khối GIÁ TRẦN nổi bật nhất trang (border đậm + nền accent) + giải thích 1 dòng &quot;tin không được vượt giá trần này&quot;</li><li>[ ] Badge enum đủ 7 trạng thái dự án (PLANNING…SUSPENDED) + 6 trạng thái pháp lý (IN_PROGRESS…DISPUTED) — màu theo docs/07 §3, nhãn tiếng Việt</li><li>[ ] Bảng loại căn (unitTypes ≤30 dòng) + chip tiện ích (amenities ≤50) — vẽ trạng thái cuộn khi dài</li><li>[ ] Row tin: ảnh thumb + thông số + <b>đơn giá /m² + ✓ dưới trần</b> + giá; biến thể badge Đang bán / Sắp đấu giá / Đã bán</li><li>[ ] KHÔNG vẽ: ảnh dự án, bản đồ GPS, % milestone, lịch thanh toán, &quot;người tạo&quot; (chưa có trong schema — cấm mock)</li><li>[ ] Trạng thái: Loading skeleton · Empty (chưa có tin) · Error + traceId · 404 &quot;Không tìm thấy dự án&quot;</li><li>[ ] Copy đúng docs/06 §5; tiền <code>30.000.000 ₫/m²</code>; ngày <code>dd/MM/yyyy HH:mm</code> GMT+7; không emoji icon production (💰/🏗 là placeholder)</li><li>[ ] Accessibility: table có caption/scope; khối giá trần đọc được bởi screen reader như 1 thông điệp (không chỉ màu)</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd nguồn giá trần OQ-4) cần PM duyệt trên docs/08 trước.</p></div>',15)])])}const w=s(l,[["render",c]]);export{r as __pageData,w as default};
